'use strict';
const FC=window.FloodCore;
let floodData={rows:[],history:[],retrievedAt:null,error:null},floodState='loading',heatMode=read('fa-heatmode','depth'),heatOn=true,showOldHeat=false,heatOffset=0,historyAt=null,floodLayers=[],heatLayer=null;
let expiryTimer=null,routeReports=[],reportData=[],reportState='loading',destinations=[],destState='loading',need='all',onlyRecent=false,accessOrigin=null,accessTarget=null,accessMode='driving',routeData=[],routeState='idle',routeError='',selectedRoute=0,picking=null,routeLayers=[],watchOn=read('fa-watch',false),lastWatch=new Map(),routeSeq=0;
const itemNames={water:['Drinking water','น้ำดื่ม'],food:['Food','อาหาร'],rice:['Rice','ข้าวสาร'],instant_food:['Instant food','อาหารสำเร็จรูป'],medicine:['Medicine','ยา'],baby_products:['Baby products','ของใช้เด็ก'],batteries:['Batteries','ถ่านไฟฉาย'],power_banks:['Power banks','พาวเวอร์แบงก์'],hygiene:['Hygiene','ของใช้สุขอนามัย'],pet_food:['Pet food','อาหารสัตว์'],opening:['Opening status','สถานะเปิดทำการ'],access:['Entrance access','การเข้าถึงทางเข้า']};
const itemName=k=>t(...(itemNames[k]||[k,k])),ago=time=>{const m=Math.max(0,Math.floor((Date.now()-time)/60000));return m<60?t(`${m}m ago`,`${m} นาทีที่แล้ว`):m<1440?t(`${Math.floor(m/60)}h ago`,`${Math.floor(m/60)} ชั่วโมงที่แล้ว`):t(`${Math.floor(m/1440)}d ago`,`${Math.floor(m/1440)} วันที่แล้ว`)};
const depthColor=d=>d===0?'#57a89b':d<10?'#f1c04d':d<30?'#eb843b':'#ca4345';
const statusName=(item,status)=>item==='opening'?({available:t('Reported open','มีรายงานว่าเปิด'),limited:t('Reduced service','ให้บริการจำกัด'),unavailable:t('Reported closed','มีรายงานว่าปิด')}[status]):item==='access'?({available:t('Reported accessible','มีรายงานว่าเข้าถึงได้'),limited:t('Access disrupted','การเข้าถึงมีอุปสรรค'),unavailable:t('Reported inaccessible','มีรายงานว่าเข้าไม่ได้')}[status]):({available:t('Reported available','มีรายงานว่ามีสินค้า'),limited:t('Reported limited','มีรายงานว่าสินค้าจำกัด'),unavailable:t('Reported unavailable','มีรายงานว่าไม่มีสินค้า')}[status]);
function activeReports(){return FC.latestReports(reportData)}
function localSensors(center=area(),radius=8){return floodData.rows.filter(r=>FC.kmBetween(center,r)<=radius)}
function readAtTime(){if(historyAt===null||view==='access')return floodData.rows;const cutoff=historyAt,rows=[...floodData.history,...floodData.rows].filter(r=>r.observedAt<=cutoff).sort((a,b)=>b.observedAt-a.observedAt),result=new Map();for(const r of rows)if(!result.has(r.id))result.set(r.id,r);return [...result.values()]}
function timeReference(){return view==='access'||historyAt===null?Date.now():historyAt}
function historyBounds(){const times=[...floodData.history,...floodData.rows].map(r=>r.observedAt).filter(Number.isFinite);return {min:times.length?Math.max(Date.now()-30*86400000,Math.min(...times)):Date.now(),max:Date.now(),latest:times.length?Math.max(...times):null}}
function bangkokInput(time){return new Date(time+7*3600000).toISOString().slice(0,16)}
function historyLabel(){return historyAt===null?t('Now','ตอนนี้')+' · '+stamp(Date.now())+' ICT':stamp(historyAt)+' ICT · '+t('Historical view','ข้อมูลย้อนหลัง')}
function setHistory(time){const b=historyBounds();historyAt=time===null?null:Math.max(b.min,Math.min(b.max,time));heatOffset=historyAt===null?0:(Date.now()-historyAt)/3600000;render()}

function trendName(k){return ({rising:t('Rising','เพิ่มขึ้น'),draining:t('Draining','ลดลง'),stable:t('Stable','คงที่'),unknown:t('Trend unknown','ยังไม่ทราบแนวโน้ม')})[k]}
function heatSummary(){const rows=localSensors(),fresh=rows.filter(r=>FC.fresh(r));return {rows,fresh,wet:fresh.filter(r=>r.depth>0),stale:rows.length-fresh.length}}
const originalNav=navItems;navItems=function(){const a=originalNav();a.splice(2,0,['access','road',t('Can I get there?','ตรวจเส้นทาง')]);return a};
const originalNotice=notice;notice=function(){const s=heatSummary();return `<div class="notice ${s.fresh.length?'coverage-notice':''}">${ic('waves')}<div><strong>${s.fresh.length?t(`${s.fresh.length} recent sensor readings within 8 km`,`${s.fresh.length} จุดวัดล่าสุด ภายใน 8 กม.`):floodState==='loading'?t('Checking road-water observations…','กำลังตรวจสอบข้อมูลระดับน้ำบนถนน…'):t('Current street-level coverage is incomplete','ข้อมูลปัจจุบันระดับถนนยังไม่ครบถ้วน')}</strong>${s.fresh.length?t(`${s.wet.length} report water above zero. Unmonitored streets remain unknown.`,`${s.wet.length} จุดมีน้ำสูงกว่า 0 ซม. ถนนที่ไม่มีจุดวัดยังไม่ทราบสถานะ`):t('Old readings are gray. Areas without measurements are unknown, not clear.','ข้อมูลเก่าเป็นสีเทา พื้นที่ไม่มีข้อมูลคือไม่ทราบ ไม่ใช่ไม่มีน้ำท่วม')}</div><button data-action="heatmap">${t('Open heatmap','เปิดแผนที่ความเข้ม')}</button></div>`};
const originalOverview=overview;overview=function(){let html=originalOverview();html=html.replace(/<section class="card wide-card"><div class="row between"><h2>.*?<\/section>$/s,'');return featureBar()+html+destinationMini()};
function featureBar(){return `<section class="hero-features"><button data-action="heatmap"><span class="feature-symbol">${ic('waves')}</span><span><strong>${t('Where is the water?','น้ำอยู่ตรงไหน?')}</strong><small>${t('Depth, freshness & change','ระดับน้ำ ความสดใหม่ และแนวโน้ม')}</small></span></button><button data-view="access"><span class="feature-symbol">${ic('road')}</span><span><strong>${t('Can I get there?','เดินทางไปได้ไหม?')}</strong><small>${t('Check the journey and the last 300 m','ตรวจเส้นทางและ 300 ม. สุดท้าย')}</small></span></button><button data-view="supplies"><span class="feature-symbol">${ic('bag')}</span><span><strong>${t('Can I get what I need?','หาของจำเป็นได้ที่ไหน?')}</strong><small>${t('Recent supply reports & access','รายงานสินค้าและการเข้าถึงล่าสุด')}</small></span></button></section>`}
function destinationMini(){return `<section class="card wide-card"><div class="row between"><h2>${t('Places that matter','สถานที่สำคัญของคุณ')}</h2><button data-view="access">${ic('star')}${t('Manage destinations','จัดการจุดหมาย')}</button></div><div class="saved-list" style="margin-top:16px">${destinations.length?destinations.map(d=>{const n=localSensors(d,.3).filter(r=>FC.fresh(r)&&r.depth>0).length;return `<button data-destination="${esc(d.id)}">${ic('pin')}${esc(d.label)} · ${n?t(`${n} nearby water observations`,`${n} จุดวัดมีน้ำใกล้เคียง`):t('Access unknown','ไม่ทราบการเข้าถึง')}</button>`}).join(''):`<p class="sub">${destState==='error'?t('Saved destinations unavailable. Try refreshing.','โหลดจุดหมายไม่ได้ ลองอัปเดตอีกครั้ง'):t('Save home, school, work or family locations to your account.','บันทึกบ้าน โรงเรียน ที่ทำงาน หรือบ้านครอบครัวในบัญชีของคุณ')}</p>`}</div></section>`}
const originalMapContent=mapContent;mapContent=function(large){const s=heatSummary();let html=originalMapContent(large);html=html.replace(t('Nearby places · flood coverage unavailable','สถานที่ใกล้เคียง · ไม่มีข้อมูลน้ำท่วม'),t('Road-water sensors · nearby essentials','จุดวัดน้ำบนถนน · สถานที่จำเป็น'));html=html.replace('<div class="mapwrap',heatControls()+'<div class="mapwrap');html=html.replace(/<div class="map-meta">.*?<\/div><\/section>/s,`<div class="heat-legend"><span>${t('Depth at sensors','ระดับน้ำที่จุดวัด')}</span><span><i style="background:#57a89b"></i>0 cm</span><span><i style="background:#f1c04d"></i>1–9 cm</span><span><i style="background:#eb843b"></i>10–29 cm</span><span><i style="background:#ca4345"></i>30+ cm</span><span><i style="background:#8b9698"></i>${t('Old / unknown','เก่า / ไม่ทราบ')}</span></div><div class="coverage-caption">${t('Heat shows nearby sensor intensity, not a measured flood boundary or soil saturation. Tap a dot for evidence.','สีความเข้มแสดงค่าจุดวัดใกล้เคียง ไม่ใช่ขอบเขตน้ำท่วมจริงหรือความอิ่มตัวของดิน แตะจุดเพื่อดูหลักฐาน')}</div></section>`);if(large)html+=sensorList();return html};
function heatControls(){const bounds=historyBounds(),ref=timeReference(),count=readAtTime().filter(r=>FC.fresh(r,ref)&&r.depth>0).length;return `<div class="heat-controls"><div class="row between"><div class="segmented"><button data-heat="depth" class="${heatMode==='depth'?'active':''}">${t('Water depth (cm)','ระดับน้ำ (ซม.)')}</button><button data-heat="change" class="${heatMode==='change'?'active':''}">${t('Recent change','แนวโน้ม')}</button></div><label class="check-label"><input type="checkbox" id="heatToggle" ${heatOn?'checked':''}>${t('Heatmap','แผนที่ความเข้ม')}</label></div><label class="check-label old-heat-option"><input type="checkbox" id="oldHeatToggle" ${showOldHeat?'checked':''}>${t('Color old recorded depths (not current conditions)','แสดงสีระดับน้ำเก่า (ไม่ใช่สถานการณ์ปัจจุบัน)')}</label><div class="time-control"><b id="timeLabel">${historyLabel()}</b><input type="range" id="heatTime" ${view==='access'||!bounds.latest?'disabled':''} aria-label="${t('Measurement history','ประวัติค่าการวัด')}" min="${bounds.min}" max="${bounds.max}" step="60000" value="${historyAt??bounds.max}"><button data-action="heat-now">${t('Now','ตอนนี้')}</button><button data-action="heat-latest" ${view==='access'||!bounds.latest?'disabled':''}>${t('Latest recorded time','เวลาวัดล่าสุดที่บันทึก')}</button></div><label class="history-date">${t('Choose date and time (Bangkok / ICT)','เลือกวันที่และเวลา (กรุงเทพฯ / ICT)')}<input id="historyDate" type="datetime-local" min="${bangkokInput(bounds.min)}" max="${bangkokInput(bounds.max)}" value="${bangkokInput(ref)}" ${view==='access'||!bounds.latest?'disabled':''}></label><p class="source-note">${t('Recorded range','ช่วงที่มีการบันทึก')}: ${stamp(bounds.min)} – ${stamp(bounds.max)} ICT. ${t('Missing measurements stay unknown; data over 60 minutes before the selected time is old.','ช่วงที่ไม่มีการวัดแสดงว่าไม่ทราบ ข้อมูลเกิน 60 นาทีก่อนเวลาที่เลือกถือว่าเก่า')}</p><p id="heatStatus" class="source-note" role="status">${!heatOn?t('Heatmap is off.','ปิดแผนที่ความเข้ม'):showOldHeat?t('Colors include dated readings. Gray dashed nodes are old; open each node for its measurement time.','สีรวมค่าการวัดเก่า จุดเส้นประสีเทาคือข้อมูลเก่า เปิดจุดเพื่อดูเวลาวัด'):heatMode==='change'?t('Change view uses colored sensor markers.','แนวโน้มแสดงด้วยสีจุดวัด'):count?t(`${count} wet sensors with recent measurements at this time.`,`${count} จุดวัดมีน้ำและมีข้อมูลล่าสุด ณ เวลานี้`):t('No recent wet measurements at this time. Choose Latest recorded time to inspect older readings.','ไม่มีค่าล่าสุดที่มีน้ำ ณ เวลานี้ เลือกเวลาวัดล่าสุดที่บันทึกเพื่อดูข้อมูลเก่า')}</p></div>`}
function sensorList(){const ref=timeReference(),rows=readAtTime().filter(r=>FC.kmBetween(area(),r)<=8).sort((a,b)=>Number(FC.fresh(b,ref))-Number(FC.fresh(a,ref))||b.depth-a.depth),s={fresh:rows.filter(r=>FC.fresh(r,ref)),stale:rows.filter(r=>!FC.fresh(r,ref)).length,wet:rows.filter(r=>FC.fresh(r,ref)&&r.depth>0)};return `<div class="sensor-summary"><div><b>${s.fresh.length}</b><span>${t('recent nearby sensors','จุดวัดใกล้เคียงล่าสุด')}</span></div><div><b>${s.stale}</b><span>${t('old nearby readings','จุดวัดใกล้เคียงที่เก่า')}</span></div><div><b>${s.wet.length}</b><span>${t('currently reporting water','จุดวัดล่าสุดที่มีน้ำ')}</span></div></div><section class="card"><div class="card-head"><h2>${historyAt===null?t('Nearby measurements (cm)','ค่าการวัดใกล้เคียง (ซม.)'):t('Historical measurements (cm)','ค่าการวัดย้อนหลัง (ซม.)')}</h2><button class="text-button" data-action="all-sensors">${t('See all Bangkok sensors','ดูจุดวัดทั่วกรุงเทพฯ')}</button></div>${rows.length?rows.slice(0,8).map(r=>`<button class="sensor-row" data-sensor="${esc(r.id)}"><span class="sensor-value ${FC.fresh(r,ref)?'':'stale'}" style="--water-color:${depthColor(r.depth)}">${r.depth}<small>cm</small></span><span><strong>${esc(r.name)}</strong><small>${esc(r.district)} · ${stamp(r.observedAt)} · ${FC.fresh(r,ref)?t('Recent','ล่าสุด'):t('Stale','ข้อมูลเก่า')}</small></span><span class="badge">${FC.fresh(r,ref)?trendName(FC.trend(r,floodData.history,ref).kind):t('Not current','ไม่ใช่ปัจจุบัน')}</span></button>`).join(''):`<div class="empty">${floodState==='loading'?t('Loading sensor measurements…','กำลังโหลดค่าจุดวัด…'):t('No sensor data loaded for this area.','ไม่มีข้อมูลจุดวัดสำหรับพื้นที่นี้')}</div>`}<div class="coverage-caption">${t('BMA observations relayed by ThaiWater. Retrieved','ข้อมูล กทม. ถ่ายทอดโดย ThaiWater ดึงข้อมูลเมื่อ')} ${stamp(floodData.retrievedAt)} · <a href="https://www.thaiwater.net/" target="_blank" rel="noopener">ThaiWater</a></div></section>`}
const originalInitMap=initMap;initMap=function(){originalInitMap();if(!map)return;map.on('click',e=>{if(picking==='supply'){if(!FC.pointValid(e.latlng.lat,e.latlng.lng))return toast(t('Choose a point in Bangkok.','เลือกจุดในกรุงเทพฯ'));picking=null;newSupplyPoint(e.latlng);return}if(picking){const p={lat:e.latlng.lat,lng:e.latlng.lng,label:t('Selected map point','จุดที่เลือกบนแผนที่')};if(!FC.pointValid(p.lat,p.lng))return toast(t('Select a point in the Bangkok region.','เลือกจุดในพื้นที่กรุงเทพฯ'));if(picking==='origin')accessOrigin=p;else accessTarget=p;picking=null;routeSeq++;routeData=[];routeState='idle';render()}});drawFlood();drawRoutes()};
function drawFlood(){if(!map)return;floodLayers.forEach(l=>{try{map.removeLayer(l)}catch{}});floodLayers=[];const rows=readAtTime(),now=timeReference(),recent=rows.filter(r=>FC.fresh(r,now));if(heatOn&&heatMode==='depth'&&L.heatLayer){const points=(showOldHeat?rows:recent).filter(r=>r.depth>0).map(r=>[r.lat,r.lng,Math.min(1,r.depth/50)]);if(points.length){heatLayer=L.heatLayer(points,{radius:24,blur:12,maxZoom:14,max:1,minOpacity:.55,gradient:{.15:'#e4c344',.4:'#ee963f',.7:'#dd5d3d',1:'#ba323d'}}).addTo(map);floodLayers.push(heatLayer)}}for(const r of rows){const current=FC.fresh(r,now),tr=FC.trend(r,floodData.history,now),color=!current?'#8b9698':heatMode==='depth'?depthColor(r.depth):tr.kind==='rising'?'#d46c3f':tr.kind==='draining'?'#3d92a5':tr.kind==='stable'?'#6576a2':'#8b9698';const m=L.circleMarker([r.lat,r.lng],{radius:current?7:5,color:current?'#fff':'#68777c',weight:current?2:1,dashArray:current?null:'2 3',fillColor:color,fillOpacity:current?.95:.35}).addTo(map).bindTooltip(`${r.depth} cm`,{permanent:true,direction:'top',className:current?'water-label':'water-label stale'});m.on('click',()=>openSensor(r));floodLayers.push(m)}
if(view==='access'&&accessTarget){const halo=L.circle([accessTarget.lat,accessTarget.lng],{radius:300,color:'#497b94',weight:1,dashArray:'5 7',fillOpacity:.04}).addTo(map);floodLayers.push(halo)}}
function openSensor(r){const current=FC.fresh(r,timeReference()),tr=FC.trend(r,floodData.history,timeReference()),history=floodData.history.filter(x=>x.id===r.id).sort((a,b)=>b.observedAt-a.observedAt).slice(0,8);showDialog(`${historyAt!==null?`<p class="notice">${t('Historical measurement — not current conditions','ค่าการวัดย้อนหลัง ไม่ใช่สถานการณ์ปัจจุบัน')} · ${stamp(timeReference())} ICT</p>`:''}<span class="badge">${t('Official sensor via ThaiWater','จุดวัดทางการผ่าน ThaiWater')}</span><h2>${esc(r.name)}</h2><div class="big-depth ${current?'':'stale'}">${r.depth}<small>cm</small></div><p class="${current?'source-note':'notice'}">${current?t('Observed at the sensor; surrounding road conditions may differ.','วัดเฉพาะที่จุดติดตั้ง สภาพถนนโดยรอบอาจต่างกัน'):t('Old measurement — not evidence of current conditions.','ค่าการวัดเก่า ไม่ใช่หลักฐานสถานการณ์ปัจจุบัน')}</p><div class="detail-lines"><p><span>${t('Measured','เวลาวัด')}</span>${stamp(r.observedAt)}</p><p><span>${t('Change','แนวโน้ม')}</span>${trendName(tr.kind)}${tr.delta!==null?' ('+(tr.delta>0?'+':'')+tr.delta+' cm)':''}</p><p><span>${t('Coverage','ความครอบคลุม')}</span>${t('Sensor location only','เฉพาะตำแหน่งจุดวัด')}</p></div><h3>${t('Recorded observations','ประวัติค่าการวัด')}</h3>${history.length?history.map(h=>`<div class="history-row"><span>${stamp(h.observedAt)}</span><b>${h.depth} cm</b></div>`).join(''):`<p class="source-note">${t('No additional observations recorded yet.','ยังไม่มีค่าการวัดอื่นที่บันทึกไว้')}</p>`}<a class="button" href="https://www.thaiwater.net/" target="_blank" rel="noopener">${t('Open source','เปิดแหล่งข้อมูล')}</a>`)}
function showDialog(content){const d=$('#detail');d.innerHTML=`<button class="icon close" aria-label="${t('Close','ปิด')}">${ic('close')}</button>${content}`;d.querySelector('.close').onclick=()=>d.close();if(!d.open)d.showModal()}
const originalSupply=supplyContent;supplyContent=function(){let html=originalSupply();html=html.replace(/<p class="sub" style="margin-bottom:18px">.*?<\/p>/,`<div class="supply-intro"><div><h2>${t('Find it. Check it. Get there.','ค้นหา ตรวจสอบ แล้วเดินทาง')}</h2><p class="sub">${t('Recent observations, with source and expiry. No report is a stock guarantee.','ข้อมูลที่พบล่าสุดพร้อมแหล่งที่มาและวันหมดอายุ ไม่ใช่การรับประกันสินค้า')}</p></div><span class="badge">${t('Community evidence','ข้อมูลจากชุมชน')}</span></div>`);html=html.replace('<div class="filterbar">',`<div class="need-filter"><label>${t('I need','ฉันต้องการ')}<select id="needSelect"><option value="all" ${need==='all'?'selected':''}>${t('Any essential','ของจำเป็นทุกประเภท')}</option>${FC.ITEMS.filter(k=>!['opening','access'].includes(k)).map(k=>`<option value="${k}" ${need===k?'selected':''}>${itemName(k)}</option>`).join('')}</select></label><label class="check-label"><input id="onlyRecent" type="checkbox" ${onlyRecent?'checked':''}>${t('Recent availability reports only','เฉพาะรายงานว่ามีสินค้าล่าสุด')}</label></div>${reportState==='error'?`<p class="notice">${t('Supply reports could not load. Availability is unknown.','โหลดรายงานสินค้าไม่ได้ สถานะสินค้าไม่ทราบ')}</p>`:''}<div class="filterbar">`);return html+`<section class="card wide-card"><h2>${t('Know a local supply point?','รู้จักจุดแจกจ่ายหรือร้านค้าในพื้นที่?')}</h2><p class="sub">${t('Add a place you have visited and share a recent observation, even if directory search is unavailable.','เพิ่มสถานที่ที่คุณไปมาและแจ้งสิ่งที่พบล่าสุดได้ แม้ระบบค้นหาร้านค้าจะไม่พร้อม')}</p><button style="margin-top:15px" data-action="add-supply-point">${ic('pin')}${t('Mark a supply point on the map','ระบุจุดสิ่งของจำเป็นบนแผนที่')}</button></section>`};
filtered=function(){const ar=activeReports();return places.filter(p=>(filter==='all'||p.kind===filter)&&`${p.en} ${p.th}`.toLowerCase().includes(query.toLowerCase())&&(!onlyRecent||ar.some(r=>r.placeId===p.id&&(need==='all'?!['opening','access'].includes(r.item):r.item===need)&&['available','limited'].includes(r.status)&&!r.disputes))).sort((a,b)=>{const score=p=>{const rs=ar.filter(r=>r.placeId===p.id),available=rs.some(r=>(need==='all'?!['opening','access'].includes(r.item):r.item===need)&&r.status==='available'&&!r.disputes),closed=rs.some(r=>['opening','access'].includes(r.item)&&r.status==='unavailable');const evidence=rs.filter(r=>(need==='all'?!['opening','access'].includes(r.item):r.item===need)&&r.status==='available'&&!r.disputes);const corroborated=evidence.some(r=>r.confirmations>0);const newest=evidence.length?Math.max(...evidence.map(r=>r.observedAt)):0;return (available?4:0)+(corroborated?2:0)+(newest?Math.max(0,1-(Date.now()-newest)/7200000):0)-(closed?8:0)};return score(b)-score(a)||a.distance-b.distance})};
function placeReports(p){return activeReports().filter(r=>r.placeId===p.id)}
function summaryFor(p,item){const r=placeReports(p).find(r=>r.item===item);return r?`${statusName(item,r.status)}${r.disputes?' · '+t('Disputed','มีข้อโต้แย้ง'):''}`:t('Unknown','ไม่ทราบ')}
placeCards=function(ps){if(!ps.length)return `<div class="card empty" style="grid-column:1/-1">${placeState==='loading'?t('Finding nearby places…','กำลังค้นหาสถานที่…'):onlyRecent?t('No recent matching availability reports. Turn off this filter to see places you can contact.','ไม่มีรายงานสินค้าล่าสุดที่ตรงกัน ปิดตัวกรองเพื่อดูร้านค้าที่ติดต่อได้'):t('No places found. Try refreshing or use Google Maps below.','ไม่พบสถานที่ ลองอัปเดตหรือใช้ Google Maps ด้านล่าง')}</div>`;return ps.slice(0,60).map(p=>{const rs=placeReports(p),stock=rs.filter(r=>!['opening','access'].includes(r.item)&&(need==='all'||r.item===need));return `<section class="card place"><div class="row between"><div class="resource-icon">${ic(p.kind==='store'?'bag':'cross')}</div><span class="badge">${kindName(p.kind)}</span></div><h3>${esc(name(p))}</h3><p class="sub">${p.distance.toFixed(1)} km · ${t('straight line from area center','ระยะเส้นตรงจากใจกลางพื้นที่')}</p><div class="stock-tags">${stock.length?stock.slice(0,3).map(r=>`<span class="stock-tag ${r.status} ${r.disputes?'disputed':''}">${itemName(r.item)} · ${statusName(r.item,r.status)}<small>${ago(r.observedAt)}${r.disputes?' · '+t('Disputed','มีข้อโต้แย้ง'):''}</small></span>`).join(''):`<span class="stock-tag unknown">${t('Stock not yet reported','ยังไม่มีรายงานสินค้า')}</span>`}</div><dl><dt>${t('Opening status','สถานะเปิดทำการ')}</dt><dd>${summaryFor(p,'opening')}</dd><dt>${t('Entrance access','การเข้าถึงทางเข้า')}</dt><dd>${summaryFor(p,'access')}</dd></dl><button data-place="${esc(p.id)}">${t('Check evidence & availability','ดูหลักฐานและสินค้า')}</button><button class="text-button" data-plan-place="${esc(p.id)}">${ic('road')}${t('Check the journey','ตรวจสอบการเดินทาง')}</button></section>`}).join('')};
const originalOpenPlace=openPlace;openPlace=function(id){const p=places.find(p=>p.id===id);if(!p)return;if(p.community){showDialog(`<span class="badge">${t('Community-listed place · unverified','สถานที่จากชุมชน · ยังไม่ยืนยัน')}</span><h2>${esc(name(p))}</h2><p class="sub">${p.distance.toFixed(1)} km · ${t('from district center','จากใจกลางเขต')}</p><div class="detail-lines"></div><a class="button" href="https://www.google.com/maps/dir/?api=1&destination=${p.lat},${p.lng}" target="_blank" rel="noopener">${t('Ordinary directions','เส้นทางปกติ')}</a>`)}else originalOpenPlace(id);const d=$('#detail');const lines=d.querySelectorAll('.detail-lines p');if(lines[0])lines[0].innerHTML=`<span>${t('Opening status','สถานะเปิดทำการ')}</span>${summaryFor(p,'opening')}`;if(lines[1])lines[1].innerHTML=`<span>${t('Entrance access','การเข้าถึงทางเข้า')}</span>${summaryFor(p,'access')}`;d.insertAdjacentHTML('beforeend',`<div class="evidence-section"><div class="row between"><h3>${t('Availability & access reports','รายงานสินค้าและการเข้าถึง')}</h3><button data-new-report="${esc(id)}">${t('Add update','แจ้งข้อมูล')}</button></div><p class="source-note">${t('Supply reports expire after 2 hours; opening and entrance reports after 1 hour. Merchant identity is self-declared, not verified.','รายงานสินค้าหมดอายุใน 2 ชั่วโมง สถานะเปิดและทางเข้าใน 1 ชั่วโมง ผู้รายงานว่าตนเป็นร้านค้ายังไม่ผ่านการยืนยันตัวตน')}</p><div id="reportHistory" data-place-id="${esc(id)}">${t('Loading reports…','กำลังโหลดรายงาน…')}</div><button data-plan-place="${esc(id)}">${ic('road')}${t('Check access to this place','ตรวจสอบการเข้าถึงสถานที่นี้')}</button></div>`);wireUpgrade(d);loadPlaceReports(id)};
async function loadPlaceReports(id){try{const data=await apiJSON('/api/reports?place='+encodeURIComponent(id));if(!$('#reportHistory')||$('#reportHistory').dataset.placeId!==id)return;if(data.backendRequired){$('#reportHistory').textContent=t('Shared supply reports are not connected. Stock and entrance access are unknown. Check with the store directly.','ยังไม่ได้เชื่อมต่อรายงานสินค้าร่วมกัน สต็อกและทางเข้ายังไม่ทราบ โปรดตรวจสอบกับร้านค้าโดยตรง');$('#detail').querySelector('[data-new-report]')?.remove();return}$('#reportHistory').innerHTML=data.reports.length?data.reports.map(r=>`<article class="report-card ${r.expiresAt<=Date.now()?'expired':''}"><div class="row between"><b>${itemName(r.item)}</b><span class="badge">${r.expiresAt<=Date.now()?t('Expired','หมดอายุ'):r.disputes?t('Disputed','มีข้อโต้แย้ง'):t('Unverified report','รายงานยังไม่ยืนยัน')}</span></div><p>${statusName(r.item,r.status)}</p>${r.note?`<p class="report-note">${esc(r.note)}</p>`:''}<small>${r.role==='merchant'?t('Self-declared shop representative','ผู้ระบุว่าตนเป็นตัวแทนร้าน'):t('Community visitor','ผู้เยี่ยมชมในชุมชน')} · ${stamp(r.observedAt)}<br>${t('Expires','หมดอายุ')} ${stamp(r.expiresAt)} · ${r.confirmations} ${t('independent confirmations','คนยืนยันเพิ่มเติม')} / ${r.disputes} ${t('disputes','คนโต้แย้ง')}</small>${!r.mine&&r.expiresAt>Date.now()?`<div class="row" style="margin-top:12px"><button data-vote="confirm" data-report-id="${esc(r.id)}" data-place-id="${esc(id)}">${t('I can confirm','ฉันยืนยันได้')}</button><button data-vote="dispute" data-report-id="${esc(r.id)}" data-place-id="${esc(id)}">${t('This has changed','ข้อมูลเปลี่ยนแล้ว')}</button></div>`:''}</article>`).join(''):`<div class="empty">${t('No recent reports. Add what you personally observed, or call the place to check.','ยังไม่มีรายงานล่าสุด แจ้งสิ่งที่คุณพบด้วยตนเอง หรือโทรสอบถามสถานที่')}</div>`;wireUpgrade($('#detail'))}catch(e){if($('#reportHistory'))$('#reportHistory').textContent=t('Reports unavailable. Try opening this place again.','โหลดรายงานไม่ได้ ลองเปิดสถานที่นี้อีกครั้ง')}}
function reportForm(id){const p=places.find(p=>p.id===id);if(!p)return;showDialog(`<p class="eyebrow">${t('SHARE WHAT YOU OBSERVED','แจ้งสิ่งที่คุณพบ')}</p><h2>${esc(name(p))}</h2><form id="reportForm" class="field-form"><label>${t('What are you updating?','คุณต้องการแจ้งเรื่องใด?')}<select name="item" id="reportItem">${FC.ITEMS.map(k=>`<option value="${k}" ${need===k||(need==='all'&&k==='water')?'selected':''}>${itemName(k)}</option>`).join('')}</select></label><label>${t('Status','สถานะ')}<select name="status" id="reportStatus"></select></label><label>${t('When did you see this?','คุณพบข้อมูลนี้เมื่อใด?')}<select name="minutesAgo"><option value="0">${t('Just now','เมื่อสักครู่')}</option><option value="15">${t('15 minutes ago','15 นาทีที่แล้ว')}</option><option value="30">${t('30 minutes ago','30 นาทีที่แล้ว')}</option></select></label><label>${t('Your relationship to this place','ความเกี่ยวข้องกับสถานที่')}<select name="role"><option value="visitor">${t('I visited this place','ฉันไปที่นี่มา')}</option><option value="merchant">${t('I work here (self-declared)','ฉันทำงานที่นี่ (ยังไม่ยืนยัน)')}</option></select></label><label>${t('Additional detail (optional)','รายละเอียดเพิ่มเติม (ไม่บังคับ)')}<textarea name="note" maxlength="400" rows="3" placeholder="${t('Item, entrance or service details. No personal information.','รายละเอียดสินค้า ทางเข้า หรือบริการ ไม่ใส่ข้อมูลส่วนตัว')}"></textarea></label><p class="source-note">${t('This will be visible to people who can access this site, labeled as an unverified report.','ผู้เข้าถึงเว็บไซต์นี้จะเห็นรายงานของคุณ โดยระบุว่ายังไม่ยืนยัน')}</p><p id="formError" class="form-error" role="alert"></p><button class="primary" type="submit">${t('Submit observation','ส่งข้อมูลที่พบ')}</button></form>`);const update=()=>{$('#reportStatus').innerHTML=['available','limited','unavailable'].map(s=>`<option value="${s}">${statusName($('#reportItem').value,s)}</option>`).join('')};update();$('#reportItem').onchange=update;$('#reportForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;const b=Object.fromEntries(new FormData(e.target));try{await apiJSON('/api/reports',{method:'POST',body:JSON.stringify({...b,placeId:p.id,placeName:name(p),lat:p.lat,lng:p.lng,minutesAgo:Number(b.minutesAgo)})});await loadReports();openPlace(id);toast(t('Observation saved with an expiry time.','บันทึกรายงานพร้อมเวลาหมดอายุแล้ว'))}catch(error){$('#formError').textContent=error.message;button.disabled=false}}}
function accessContent(){const o=accessOrigin||{...area(),label:t('District center','ใจกลางเขต')};return `<p class="sub" style="margin-bottom:20px">${t('Compare mapped car routes with nearby observations. A route with fewer reports is not necessarily safer.','เปรียบเทียบเส้นทางรถยนต์กับข้อมูลใกล้เคียง เส้นทางที่มีรายงานน้อยกว่าไม่ได้แปลว่าปลอดภัยกว่า')}</p><div class="access-layout"><section class="card trip-panel"><h2>${t('Your journey','การเดินทางของคุณ')}</h2><div class="trip-stop"><span>A</span><div><small>${t('From','จาก')}</small><strong>${esc(o.label||name(area()))}</strong><small>${o.lat.toFixed(4)}, ${o.lng.toFixed(4)}</small></div></div><div class="row"><button data-action="origin-gps">${ic('locate')}${t('My location','ตำแหน่งของฉัน')}</button><button data-pick="origin">${t('Choose on map','เลือกบนแผนที่')}</button></div><div class="trip-stop"><span>B</span><div><small>${t('Destination','จุดหมาย')}</small><strong>${accessTarget?esc(accessTarget.label):t('Choose a destination','เลือกจุดหมาย')}</strong>${accessTarget?`<small>${accessTarget.lat.toFixed(4)}, ${accessTarget.lng.toFixed(4)}</small>`:''}</div></div><select id="destinationSelect" aria-label="${t('Select destination','เลือกจุดหมาย')}"><option value="">${t('Saved destination or nearby place…','จุดหมายที่บันทึกหรือสถานที่ใกล้เคียง…')}</option>${destinations.map(d=>`<option value="saved:${esc(d.id)}">★ ${esc(d.label)}</option>`).join('')}${places.slice(0,60).map(p=>`<option value="place:${esc(p.id)}">${esc(name(p))}</option>`).join('')}</select><button data-pick="destination" style="width:100%;margin-top:10px">${ic('pin')}${t('Pick destination on map','เลือกจุดหมายบนแผนที่')}</button><label class="mode-label">${t('Travelling by','รูปแบบการเดินทาง')}<select id="travelMode"><option value="driving" ${accessMode==='driving'?'selected':''}>${t('Car','รถยนต์')}</option><option value="walking" ${accessMode==='walking'?'selected':''}>${t('Walking · destination check','เดิน · ตรวจรอบจุดหมาย')}</option><option value="motorcycle" ${accessMode==='motorcycle'?'selected':''}>${t('Motorcycle · destination check','รถจักรยานยนต์ · ตรวจรอบจุดหมาย')}</option></select></label><p class="source-note">${accessMode==='driving'?t('OSRM provides ordinary driving routes. No live traffic or flood avoidance is included.','OSRM ให้เส้นทางขับรถปกติ ไม่มีข้อมูลจราจรสดหรือการหลบน้ำท่วม'):t('Walking and motorcycle routing are not connected. Only destination surroundings will be checked.','ยังไม่เชื่อมต่อเส้นทางเดินและจักรยานยนต์ ตรวจเฉพาะบริเวณจุดหมาย')}</p><button class="primary" data-action="check-trip" ${!accessTarget||routeState==='loading'?'disabled':''} style="width:100%">${routeState==='loading'?t('Checking…','กำลังตรวจสอบ…'):t('Check available evidence','ตรวจสอบข้อมูลที่มี')}</button>${accessTarget?`<button class="text-button" data-action="save-destination">${ic('star')}${t('Save this destination','บันทึกจุดหมายนี้')}</button>`:''}<p class="form-error" role="status">${esc(routeError)}</p></section><div>${mapContent(false)}${picking?`<div class="notice">${ic('pin')}<span>${t('Tap the map to select your','แตะแผนที่เพื่อเลือก')} ${picking==='origin'?t('starting point.','จุดเริ่มต้น'):t('destination.','จุดหมาย')}</span><button data-action="cancel-pick">${t('Cancel','ยกเลิก')}</button></div>`:''}</div></div>${tripResults()}${destinationMini()}<section class="card wide-card"><div class="row between"><div><h3>${t('Watch saved destinations','ติดตามจุดหมายที่บันทึก')}</h3><p class="sub">${t('While this page is open, notify me when new water observations appear within 300 m of a saved place.','ขณะเปิดหน้านี้ แจ้งเมื่อมีข้อมูลน้ำใหม่ในระยะ 300 ม. ของจุดหมายที่บันทึก')}</p></div><label class="check-label"><input id="watchToggle" type="checkbox" ${watchOn?'checked':''}>${t('On-page alerts','แจ้งเตือนในหน้า')}</label></div><p class="source-note">${t('Checks every 5 minutes while visible. No background push alerts or predictions of isolation.','ตรวจทุก 5 นาทีขณะเปิดหน้า ไม่มีการแจ้งเตือนเบื้องหลังหรือพยากรณ์การถูกตัดขาด')}</p>${destinations.map(d=>`<div class="saved-manage"><span>${esc(d.label)}</span><button data-delete-destination="${esc(d.id)}">${t('Remove','ลบ')}</button></div>`).join('')}</section>`}
function tripResults(){if(!accessTarget)return '';const near=localSensors(accessTarget,.3),recent=near.filter(r=>FC.fresh(r)),wet=recent.filter(r=>r.depth>0),rs=FC.latestReports([...routeReports,...reportData]).filter(r=>r.item==='access'&&FC.kmBetween(accessTarget,r)<=.3);return `<section class="card wide-card"><p class="eyebrow">${t('THE LAST 300 METERS','300 เมตรสุดท้าย')}</p><h2>${esc(accessTarget.label)}</h2><div class="lastmile-grid"><div><b>${wet.length}</b><span>${t('recent water observations','จุดวัดล่าสุดที่มีน้ำ')}</span></div><div><b>${near.length-recent.length}</b><span>${t('stale observations','ค่าการวัดที่เก่า')}</span></div><div><b>${rs.length}</b><span>${t('entrance reports','รายงานทางเข้า')}</span></div></div><p class="sub">${recent.length||rs.length?t('These are nearby observations. They do not establish that this entrance or every access road is passable.','ข้อมูลเหล่านี้อยู่ใกล้เคียง ไม่ได้ยืนยันว่าทางเข้าหรือถนนทุกเส้นสัญจรได้'):t('No recent observations near this destination. Entrance and surrounding streets are unknown.','ไม่มีข้อมูลล่าสุดใกล้จุดหมายนี้ ยังไม่ทราบสภาพทางเข้าและถนนโดยรอบ')}</p>${rs.map(r=>`<p class="source-note">${esc(r.placeName)} · ${statusName('access',r.status)} · ${ago(r.observedAt)} · ${t('Community report','รายงานชุมชน')}</p>`).join('')}</section>${routeData.length?`<div class="route-cards">${routeData.map((r,i)=>{const a=FC.assessRoute(r.coordinates,floodData.rows,routeReports);return `<button class="card route-card ${i===selectedRoute?'selected':''}" data-route="${i}"><span class="eyebrow">${t('ROUTE','เส้นทาง')} ${i+1}${i===0?' · '+t('OSRM default','ค่าเริ่มต้น OSRM'):''}</span><strong>${(r.distance/1000).toFixed(1)} km <small>~${Math.round(r.duration/60)} ${t('min*','นาที*')}</small></strong><span>${a.waterPoints.length} ${t('recent water points nearby','จุดวัดล่าสุดมีน้ำใกล้เส้นทาง')}</span><span>${a.accessReports.length} ${t('reported access disruptions','รายงานการเข้าถึงมีอุปสรรค')}</span><small>${a.recentSensorCount} ${t('recent sensors','จุดวัดล่าสุด')} · ${a.staleCount} ${t('stale','เก่า')}<br>${t('Unmonitored sections: unknown','ช่วงถนนที่ไม่มีจุดวัด: ไม่ทราบ')}</small></button>`}).join('')}</div><p class="source-note"><a href="https://routing.openstreetmap.de/about.html" target="_blank" rel="noopener">FOSSGIS / OSRM</a> · <a href="https://www.openstreetmap.org/fixthemap" target="_blank" rel="noopener">OpenStreetMap</a><br>${t('*Ordinary driving estimate; does not account for flood delays. Observations within 100 m may concern a parallel road. No route is certified safe.','*เวลาเดินทางปกติ ไม่รวมความล่าช้าจากน้ำท่วม จุดวัดภายใน 100 ม. อาจอยู่บนถนนคู่ขนาน ไม่มีเส้นทางใดได้รับการรับรองว่าปลอดภัย')}</p>`:''}<a class="button" href="https://www.google.com/maps/dir/?api=1&destination=${accessTarget.lat},${accessTarget.lng}" target="_blank" rel="noopener">${t('Open ordinary directions','เปิดเส้นทางปกติ')}</a>`}
function drawRoutes(){if(!map)return;routeLayers=[];if(view==='access'){const o=accessOrigin||area();for(const [p,label]of [[o,'A'],[accessTarget,'B']])if(p){const m=L.marker([p.lat,p.lng],{icon:L.divIcon({className:'',html:`<div class="trip-pin">${label}</div>`,iconSize:[30,30],iconAnchor:[15,15]})}).addTo(map);routeLayers.push(m)}routeData.forEach((r,i)=>{const line=L.polyline(r.coordinates.map(c=>[c[1],c[0]]),{color:i===selectedRoute?'#255c88':'#9aabb6',weight:i===selectedRoute?6:3,opacity:i===selectedRoute?.9:.5}).addTo(map);line.on('click',()=>{selectedRoute=i;render()});routeLayers.push(line)});const selected=routeData[selectedRoute];if(selected){for(const p of FC.assessRoute(selected.coordinates,floodData.rows,routeReports).waterPoints){routeLayers.push(L.circleMarker([p.lat,p.lng],{radius:11,color:'#c54f35',weight:3,fillOpacity:.2}).addTo(map).on('click',()=>openSensor(p)))}}}}
async function checkTrip(){if(!accessTarget)return;heatOffset=0;historyAt=null;routeError='';routeState='loading';routeData=[];const seq=++routeSeq;render();const o=accessOrigin||area(),target={...accessTarget};try{const evidence=await apiJSON('/api/reports?scope=access');if(seq!==routeSeq)return;routeReports=evidence.reports;if(accessMode==='driving'){const data=await apiJSON(`/api/route?from=${o.lat},${o.lng}&to=${target.lat},${target.lng}`);if(seq!==routeSeq)return;routeData=data.routes;selectedRoute=0}routeState='ready';render();if(map&&routeData.length)map.fitBounds(L.latLngBounds(routeData[0].coordinates.map(c=>[c[1],c[0]])),{padding:[45,45]});else map?.flyTo([target.lat,target.lng],16)}catch(e){if(seq!==routeSeq)return;routeState='error';routeError=t('Route service unavailable. Check destination evidence below or open ordinary directions.','บริการเส้นทางไม่พร้อม ตรวจข้อมูลจุดหมายด้านล่างหรือเปิดเส้นทางปกติ');render()}}
function saveDestinationForm(){if(!accessTarget)return;showDialog(`<h2>${t('Save destination','บันทึกจุดหมาย')}</h2><form id="saveDestinationForm" class="field-form"><label>${t('Name','ชื่อ')}<input name="label" required maxlength="100" value="${esc(accessTarget.label)}" placeholder="${t('Home, school, family…','บ้าน โรงเรียน ครอบครัว…')}"></label><p class="source-note">${t('Saved privately to your signed-in account.','บันทึกส่วนตัวในบัญชีที่ลงชื่อเข้าใช้')}</p><p class="form-error" id="formError"></p><button class="primary">${t('Save','บันทึก')}</button></form>`);$('#saveDestinationForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await apiJSON('/api/destinations',{method:'POST',body:JSON.stringify({label:new FormData(e.target).get('label'),lat:accessTarget.lat,lng:accessTarget.lng,mode:accessMode})});await loadDestinations();$('#detail').close();render();toast(t('Destination saved.','บันทึกจุดหมายแล้ว'))}catch(error){$('#formError').textContent=error.message;b.disabled=false}}}
