const originalWire=wire;wire=function(){originalWire();wireUpgrade(document)};
function wireUpgrade(root){root.querySelectorAll('[data-heat]').forEach(b=>b.onclick=()=>{heatMode=b.dataset.heat;save('fa-heatmode',heatMode);render()});root.querySelectorAll('[data-sensor]').forEach(b=>b.onclick=()=>{const r=readAtTime().find(r=>r.id===b.dataset.sensor);if(r){openSensor(r)}});root.querySelectorAll('[data-plan-place]').forEach(b=>b.onclick=()=>{const p=places.find(p=>p.id===b.dataset.planPlace);if(p)chooseTarget(p)});root.querySelectorAll('[data-new-report]').forEach(b=>b.onclick=()=>reportForm(b.dataset.newReport));root.querySelectorAll('[data-destination]').forEach(b=>b.onclick=()=>{const d=destinations.find(d=>d.id===b.dataset.destination);if(d)chooseTarget(d)});root.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{selectedRoute=Number(b.dataset.route);render()});root.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{picking=b.dataset.pick;render();$('#map')?.scrollIntoView({behavior:'smooth',block:'center'})});root.querySelectorAll('[data-vote]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await apiJSON('/api/votes',{method:'POST',body:JSON.stringify({reportId:b.dataset.reportId,vote:b.dataset.vote})});await loadReports();loadPlaceReports(b.dataset.placeId)}catch(e){toast(e.message);b.disabled=false}});root.querySelectorAll('[data-delete-destination]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await apiJSON('/api/destinations',{method:'DELETE',body:JSON.stringify({id:b.dataset.deleteDestination})});await loadDestinations();render()}catch(e){toast(e.message);b.disabled=false}});
if($('#oldHeatToggle'))$('#oldHeatToggle').onchange=e=>{showOldHeat=e.target.checked;render()};if($('#heatToggle'))$('#heatToggle').onchange=e=>{heatOn=e.target.checked;render()};if($('#heatTime')){const slider=$('#heatTime');slider.oninput=e=>{const value=Number(e.target.value);historyAt=value>=Number(e.target.max)-60000?null:value;heatOffset=historyAt===null?0:(Date.now()-historyAt)/3600000;$('#timeLabel').textContent=historyLabel();$('#historyDate').value=bangkokInput(timeReference());drawFlood()};slider.onchange=()=>render()}if($('#historyDate'))$('#historyDate').onchange=e=>{const value=Date.parse(e.target.value+':00+07:00');if(Number.isFinite(value))setHistory(value)};if($('#needSelect'))$('#needSelect').onchange=e=>{need=e.target.value;render()};if($('#onlyRecent'))$('#onlyRecent').onchange=e=>{onlyRecent=e.target.checked;render()};if($('#destinationSelect'))$('#destinationSelect').onchange=e=>{const val=e.target.value;if(val.startsWith('saved:')){const d=destinations.find(d=>d.id===val.slice(6));if(d)chooseTarget(d)}else if(val.startsWith('place:')){const p=places.find(p=>p.id===val.slice(6));if(p)chooseTarget(p)}};if($('#travelMode'))$('#travelMode').onchange=e=>{accessMode=e.target.value;routeSeq++;routeData=[];routeState='idle';routeError='';render()};if($('#watchToggle'))$('#watchToggle').onchange=e=>{watchOn=e.target.checked;save('fa-watch',watchOn);lastWatch.clear();checkWatches()};}
