let lastRenderArea=areaIndex,lastRenderView=view;
const originalRender=render;render=function(){const center=map?.getCenter(),zoom=map?.getZoom(),same=lastRenderArea===areaIndex&&lastRenderView===view;originalRender();if(map&&center&&same)map.setView(center,zoom,{animate:false});lastRenderArea=areaIndex;lastRenderView=view;const status=document.querySelectorAll('.stat')[1];if(status){const s=heatSummary();status.querySelector('.stat-value').textContent=s.wet.length?t(`${s.wet.length} water readings`,`${s.wet.length} จุดมีน้ำ`):s.fresh.length?t('Limited coverage','ข้อมูลบางส่วน'):t('Unknown','ไม่ทราบ');status.querySelector('.stat-note').textContent=t('Sensor observations, not an area risk rating','ค่าที่จุดวัด ไม่ใช่ระดับความเสี่ยงทั้งพื้นที่')}const layers=$('#layersPanel');if(layers){const small=layers.querySelector('small');if(small)small.textContent=t('Flood sensors are shown separately. No verified traffic, shelter, outage or flood-boundary feed is connected.','แสดงจุดวัดน้ำแยกต่างหาก ยังไม่มีข้อมูลการจราจร ศูนย์พักพิง ไฟดับ หรือขอบเขตน้ำท่วมที่ยืนยันแล้ว')}if(view==='alerts'){const noticeEl=document.querySelector('.alert-list');if(noticeEl)noticeEl.insertAdjacentHTML('beforebegin',`<section class="card wide-card" style="margin:0 0 20px"><h2>${t('Connected flood observations','ข้อมูลน้ำท่วมที่เชื่อมต่อ')}</h2><p class="sub">${t('BMA road-water readings via ThaiWater. Each station retains its own measurement timestamp.','ค่าระดับน้ำบนถนน กทม. ผ่าน ThaiWater แต่ละจุดแสดงเวลาวัดจริง')}</p><p class="source-note">${floodData.rows.length} ${t('stations loaded','จุดวัดที่โหลด')} · ${t('Retrieved','ดึงข้อมูล')} ${stamp(floodData.retrievedAt)}<br>${t('These are observations, not automated official warnings.','เป็นข้อมูลการวัด ไม่ใช่ประกาศเตือนอัตโนมัติทางการ')}</p><a class="button" href="https://www.thaiwater.net/" target="_blank" rel="noopener">ThaiWater</a></section>`)} };
async function apiJSON(url,options={}){const r=await fetch(url,{...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...options.headers},signal:AbortSignal.timeout(48000)});let d;try{d=await r.json()}catch{throw Error(t('The service returned an unreadable response. Try again.','ข้อมูลตอบกลับไม่ถูกต้อง ลองอีกครั้ง'))}if(!r.ok)throw Error(r.status===401?t('Please sign in to this site before saving.','กรุณาลงชื่อเข้าใช้เว็บไซต์ก่อนบันทึก'):d.error||t('Service unavailable. Try again.','บริการไม่พร้อม ลองอีกครั้ง'));return d}
async function loadReports(){const idx=areaIndex,a={...area()};try{const d=await apiJSON(`/api/reports?lat=${a.lat}&lng=${a.lng}`);if(idx===areaIndex){reportData=d.reports;reportState='ready';mergeCommunityPlaces();scheduleExpiry()}}catch{if(idx===areaIndex)reportState='error'}}
function scheduleExpiry(){if(expiryTimer)clearTimeout(expiryTimer);const next=reportData.filter(r=>r.expiresAt>Date.now()).map(r=>r.expiresAt);if(!next.length)return;expiryTimer=setTimeout(()=>{mergeCommunityPlaces();if($('#placeResults')){$('#placeResults').innerHTML=placeCards(filtered());wirePlaces()}if($('#reportHistory'))loadPlaceReports($('#reportHistory').dataset.placeId);else safeRender();scheduleExpiry()},Math.max(20,Math.min(...next)-Date.now()+30))}
function mergeCommunityPlaces(){const reports=activeReports();places=places.filter(p=>!p.community||reports.some(r=>r.placeId===p.id));const ids=new Set(places.map(p=>p.id));for(const r of reports){if(!ids.has(r.placeId)){places.push({id:r.placeId,en:r.placeName,th:r.placeName,lat:r.lat,lng:r.lng,kind:'store',community:true,distance:FC.kmBetween(area(),r)});ids.add(r.placeId)}}}
function newSupplyPoint(point){showDialog(`<p class="eyebrow">${t('COMMUNITY SUPPLY POINT','จุดสิ่งของจำเป็นจากชุมชน')}</p><h2>${t('Name this place','ระบุชื่อสถานที่')}</h2><form id="localPlaceForm" class="field-form"><label>${t('Store or relief-point name','ชื่อร้านหรือจุดแจกจ่าย')}<input name="name" required maxlength="160" placeholder="${t('Name people will recognize','ชื่อที่คนในพื้นที่รู้จัก')}"></label><p class="source-note">${point.lat.toFixed(5)}, ${point.lng.toFixed(5)} · ${t('Location selected on the map. This is not an officially verified relief center.','ตำแหน่งที่เลือกบนแผนที่ ไม่ใช่ศูนย์ช่วยเหลือที่ยืนยันโดยทางการ')}</p><button class="primary">${t('Continue to observation','ต่อไป: แจ้งสิ่งที่พบ')}</button></form>`);$('#localPlaceForm').onsubmit=e=>{e.preventDefault();const label=String(new FormData(e.target).get('name')||'').trim();if(!label)return;const p={id:'community-'+crypto.randomUUID(),en:label,th:label,lat:point.lat,lng:point.lng,kind:'store',community:true,distance:FC.kmBetween(area(),point)};places.push(p);reportForm(p.id)}}
async function loadDestinations(){try{const d=await apiJSON('/api/destinations');destinations=d.destinations;destState='ready';checkWatches()}catch{destState='error'}}
function safeRender(){if(!$('#detail').open&&!picking&&!document.activeElement?.matches('input,textarea,select'))render()}
loadData=async function(force=false){const rid=++request,idx=areaIndex,a={...area()},wc=read('fa-weather-'+idx,null),pc=read('fa-places-'+idx,null);if(wc){weather=wc.data;weatherStamp=wc.at;weatherState='cached'}if(pc){places=pc.data;placeStamp=pc.at;placeState='cached'}safeRender();if(!navigator.onLine){const fc=read('fa-flood',null);if(fc){floodData=fc;floodState='cached'}safeRender();return}await Promise.allSettled([(async()=>{try{const d=await getJSON(`https://api.open-meteo.com/v1/forecast?latitude=${a.lat}&longitude=${a.lng}&current=temperature_2m,relative_humidity_2m,precipitation,weather_code,wind_speed_10m&hourly=precipitation_probability,precipitation,weather_code&daily=temperature_2m_max,temperature_2m_min,precipitation_sum&timezone=Asia%2FBangkok&forecast_days=3`);if(rid!==request)return;weather=d;weatherStamp=new Date().toISOString();weatherState='ready';save('fa-weather-'+idx,{data:d,at:weatherStamp})}catch{if(rid===request)weatherState=wc?'cached':'error'}if(rid===request)safeRender()})(),(async()=>{try{const d=await apiJSON(`/api/places?lat=${a.lat}&lng=${a.lng}`);if(rid!==request)return;places=d.rows.map(p=>({...p,distance:FC.kmBetween(a,p)})).sort((p,q)=>p.distance-q.distance);mergeCommunityPlaces();placeStamp=d.retrievedAt;placeState=d.error?'cached':'ready';save('fa-places-'+idx,{data:places,at:placeStamp})}catch{if(rid===request)placeState=pc?'cached':'error'}if(rid===request)safeRender()})(),(async()=>{try{const d=await apiJSON('/api/flood');if(rid!==request)return;floodData=d;floodState=d.error?'cached':'ready';save('fa-flood',d);checkWatches()}catch{if(rid===request){const fc=read('fa-flood',null);if(fc)floodData=fc;floodState=fc?'cached':'error'}}if(rid===request)safeRender()})(),(async()=>{await loadReports();if(rid===request)safeRender()})(),(async()=>{await loadDestinations();if(rid===request)safeRender()})()]);if(force&&rid===request)toast(t('Updated available sources. Check each observation time.','อัปเดตแหล่งข้อมูลที่พร้อมแล้ว โปรดตรวจเวลาของแต่ละข้อมูล'))};
function checkWatches(){if(!watchOn)return;for(const d of destinations){const rows=localSensors(d,.3).filter(r=>FC.fresh(r)&&r.depth>0),signature=rows.map(r=>`${r.id}:${r.observedAt}:${r.depth}`).sort().join('|');if(lastWatch.has(d.id)&&lastWatch.get(d.id)!==signature&&rows.length)toast(t(`New water observations near ${d.label}. Check destination access.`,`มีข้อมูลน้ำใหม่ใกล้ ${d.label} โปรดตรวจสอบการเข้าถึง`));lastWatch.set(d.id,signature)}}
setInterval(()=>{if(!document.hidden&&navigator.onLine)loadData();else if(!document.hidden)safeRender()},300000);

